        // Settings reset to their default because GPAL could not use their value, each with the rejected value.
        // Internal, so not written to GPAL.yaml; LoadSettings reports them and rewrites the file.
        internal List<string> Corrected { get; } = new List<string>();

        // An unusable value is replaced with its default and recorded in Corrected, from a file or from code.
        private int Valid(string name, int value, bool usable, int fallback)
        {
            int retVal = value;

            if (false == usable)
            {
                Corrected.Add($"{name} [{value}]");
                retVal = fallback;
            }

            return retVal;
        }

        public int TypingDelay { get => typingDelay; internal set => typingDelay = Valid("typingDelay", value, 0 <= value, 0); }
        private int typingDelay = 0;

        public int MatchingPercentage { get => matchingPercentage; internal set => matchingPercentage = Valid("matchingPercentage", value, 0 <= value && 100 >= value, 67); }
        private int matchingPercentage;

