        public int YamlAliasLimit { get => yamlAliasLimit; internal set => yamlAliasLimit = Valid("yamlAliasLimit", value, 0 <= value, 5000); }
        private int yamlAliasLimit = 5000;

        public int DownloadTimeoutInSec { get => downloadTimeoutInSec; internal set => downloadTimeoutInSec = Valid("downloadTimeoutInSec", value, 0 < value, 10); }
