        internal GPALSettings(bool initialize = false)
        {
            CallIfFoundList = new List<Browser.Browser.CallIfDelegate>();
            CallIfNotFoundList = new List<Browser.Browser.CallIfDelegate>();
            AppCallIfFoundList = new List<Application.Application.CallIfDelegate>();
            AppCallIfNotFoundList = new List<Application.Application.CallIfDelegate>();

            if (true == initialize)
                Initialize();
        }
        internal GPALSettings()
        {
            CallIfFoundList = new List<Browser.Browser.CallIfDelegate>();
            CallIfNotFoundList = new List<Browser.Browser.CallIfDelegate>();
            AppCallIfFoundList = new List<Application.Application.CallIfDelegate>();
            AppCallIfNotFoundList = new List<Application.Application.CallIfDelegate>();
            Initialize();
        }
