        /// <summary>
        /// Print the published information or exception messages to the console.
        /// </summary>
        /// <param name="eventType">The event types to print to the console; NONE turns console output off [all types]</param>
        /// <returns>Fluent interface to specify more global settings</returns>
        [GPALSettings(Description = "Print specified GPAL events to the console. [none (default)]")]
        public IAllowGPALSettings WithPublishToConsole(GPALEventType eventType = GPALEventType.INFO | GPALEventType.WARNING | GPALEventType.ERROR | GPALEventType.EXCEPTION | GPALEventType.NOTICE | GPALEventType.CAUTION | GPALEventType.FAILURE)
        {
            ConsoleEvents = eventType;
            if (GPALEventType.NONE == eventType)
                PublishToConsole = false;
            else
                PublishToConsole = true;
            return this;
        }

        /// <summary>
        /// Write GPAL events to a text area on a form, the way WithPublishToConsole writes them to a console.
        /// </summary>
        /// <param name="control">The text area to write to, or null to stop writing to one</param>
        /// <returns>Fluent interface to specify more global settings</returns>
        [GPALSettings(Description = "Write specified GPAL events to a text area on a form. [none (default)]")]
        public IAllowGPALSettings WithPublishToControl(GPALTextArea control)
        {
            PublishControl = control;
            return this;
        }

        /// <summary>
        /// Which event types reach the control given to WithPublishToControl. Defaults to all of them.
        /// </summary>
        /// <param name="eventTypes">The events to write to the control</param>
        /// <returns>Fluent interface to specify more global settings</returns>
        [GPALSettings(Description = "Which GPAL events reach the form control. [all (default)]")]
        public IAllowGPALSettings WithControlEvents(GPALEventType eventTypes)
