        /// <summary>
        /// Which event types reach an attached exception or information handler. Defaults to all of them.
        /// </summary>
        /// <param name="eventTypes">The events to hand to a handler</param>
        /// <returns>Fluent interface to specify more global settings</returns>
        [GPALSettings(Description = "Which GPAL events reach an attached handler. [all (default)]")]
        public IAllowGPALSettings WithHandlerEvents(GPALEventType eventTypes)
