        /// <summary>
        /// Indicate which event types to print to the console. Default is none
        /// </summary>
        /// <param name="eventType">The event types to print to debug; NONE turns debug output off</param>
        /// <returns>Fluent interface to specify more global settings</returns>
        [GPALSettings(Description = "Print specified GPAL events to the output window in VisualStudio. [none (default)]")]
        public IAllowGPALSettings WithPublishToDebug(GPALEventType eventType)
        {
            DebugEvents = eventType;

            if (GPALEventType.NONE == eventType)
                PublishToDebug = false;
            else
                PublishToDebug = true;

            return this;
        }
        public IAllowGPALSettings WithPublishToLogger(IGPALLogger logger)
        {
            // Add the logger instead of replacing it, so file and database loggers can both receive events.
            if (null != logger)
            {
                if (true == PublishToLoggers.Contains(logger))
                    GPAL.PublishSimpleEvent(GPALEventType.WARNING, $"This logger is already being published to, so it was not added a second time", logger, GPALObjectType.Logger);
                else
                    PublishToLoggers.Add(logger);
            }
            return this;
        }

        /// <summary>
        /// Stops publishing events to a logger, for a workflow that logged a stretch of work to its own place and
        /// is done with it.
        /// </summary>
        /// <param name="logger">The logger to stop publishing to</param>
        /// <returns>Fluent interface to specify more global settings</returns>
        public IAllowGPALSettings RemoveLogger(IGPALLogger logger)
        {
            if (null != logger)
                PublishToLoggers.Remove(logger);

            return this;
        }

