        /// <summary>
        /// Global setting to wait for time in ticks for an element to show up.
        /// Applied to every element in every workflow.
        /// Override in a unit of work using this pattern
        ///     .WithSelector(select0or)
        ///     .WaitFor(waitForInTicks)
        ///     .LeftClick()
        /// NOTE: shortcut actions like LeftClick{selector) will not waitfor
        ///     and no syntax will make them wait except this global setting
        /// </summary>
        /// <param name="waitForInTicks"></param>
        /// <returns></returns>
        public IAllowGPALSettings WithWaitFor([Milliseconds] int waitForInTicks)
        {
            WaitForInMs = waitForInTicks;
            return this;
        }


        /// <summary>
        /// Inintialize with default values
        /// </summary>
        public void Initialize()
        {
            TypingDelay = 0;
            MatchingPercentage = 67;
            SimulateMouse = false;
            StopOnNotFound = false;
            ErrorPlaceholder = "[UNABLE TO GET]";
            PublishToConsole = false;
            PublishToLoggers = new List<IGPALLogger>();
            PublishToDebug = false;
            PublishStackTrace = false;
            UserAgent = null;
            AutoUpdateWebDriver = false;
            PromptBeforeUnexpectedExit = false;
            NoFallbackRecoveryActions = false;
            ChromeDriverUpdateURL = @"https://googlechromelabs.github.io/chrome-for-testing/latest-versions-per-milestone-with-downloads.json";   // the newest driver for every chrome major, so a browser held behind stable still finds its own
            ChromeDriverZipFilename = $"chromedriver-{DriverPlatform}.zip";
            ChromeDriverFilename = @"chromedriver.exe";
            ChromeVersionRegistry = @"SOFTWARE\Google\Chrome\BLBeacon";
            EdgeDriverUpdateURL = @"https://msedgedriver.microsoft.com/";   // LATEST_RELEASE_<major>_WINDOWS names the newest driver for a major, <version>/<zip> serves it
            EdgeDriverZipFilename = $"edgedriver_{DriverPlatform}.zip";
            EdgeDriverFilename = @"msedgedriver.exe";
            EdgeVersionRegistry = @"SOFTWARE\Microsoft\Edge\BLBeacon";
            FirefoxDriverUpdateURL = @"https://api.github.com/repos/mozilla/geckodriver/releases/latest";   // the published release, the releases page loads its assets lazily so they are never in the html
            FirefoxDriverZipFilename = $"geckodriver*{DriverPlatform}.zip";
            FirefoxDriverFilename = "geckodriver.exe";
            FirefoxBinaryPathRegistry = @"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\firefox.exe";
            FirefoxVersionRegistry = @"SOFTWARE\Mozilla\Firefox Developer Edition";
            FirefoxVersionRegistry2 = @"SOFTWARE\Mozilla\Firefox";
            FirefoxDirectDownloadMimeTypes = @"application/pdf, application/vnd.ms-excel, application/msword, text/plain, application/zip";
            WaitForInMs = WaitTime.Never;
            TempProfileDirectory = @"C:\Profiles\";
            ChromeUserAgentTemplate = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/{0}.0.0.0 Safari/537.36";
            EdgeUserAgentTemplate = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/{0}.0.0.0 Edg/{0}.0.0.0 Safari/537.36";
            FirefoxUserAgentTemplate = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/{0}.0.0.0 Edg/{0}.0.0.0 Safari/537.36";
        }
        /// <summary>
        /// Clear all settings - for testing
        /// </summary>
        public void Clear()
        {
            TypingDelay = 0; // int: 0
            MatchingPercentage = 0; // int: 0
            SimulateMouse = false; // bool: false
            StopOnNotFound = false; // bool: false
            ErrorPlaceholder = null; // string: null
            PublishToConsole = false; // bool: false
            PublishToLoggers = new List<IGPALLogger>(); // Loggers: none
            PublishToDebug = false; // bool: false
            PublishStackTrace = false; // bool: false
            DriverLocation = null; // string: null
            UserAgent = null; // string: null
            AutoUpdateWebDriver = false; // bool: false
            PromptBeforeUnexpectedExit = false; // bool: false
            NoFallbackRecoveryActions = false; // bool: false
            // Leave GPAL's driver and browser data as Initialize set it; clearing it would leave the driver update with
            // no download source.
            SettingsLoaded = false;
            WaitForInMs = WaitTime.Never;
            OAuthTokenUrl = null;
            TempProfileDirectory = null;
        }

        public IAllowGPALSettings WithNoFallbackActions(bool trueFalse = true)
        {
            NoFallbackRecoveryActions = trueFalse;
            return this;
        }
    }
